  e2469bde3fcaa ("drm/amdgpu: add support for SMU version 15.0.9")
  119b828afb87d ("drm/amdgpu: Update driver if header for SMU V15.0.5")
  1849a64165ccc ("drm/amd/pm: use milliwatts for GPU power sensors")

