+static void
+sparx5_rr_neigh_entry_offload_mark(struct sparx5_rr_neigh_entry *entry,
+				   bool offloaded)
+{
+	struct neighbour *n;
+
+	if (!entry->neigh_tbl)
+		return;
+
+	n = neigh_lookup(entry->neigh_tbl, &entry->key.iaddr,
+			 entry->key.dev);
+	if (!n)
+		return;
+
+	write_lock_bh(&n->lock);
+	if (offloaded)
+		n->flags |= NTF_OFFLOADED;
+	else
+		n->flags &= ~NTF_OFFLOADED;
+	write_unlock_bh(&n->lock);
+
+	neigh_release(n);
+}
