+		 ANA_L3_ARP_CFG_0_MAC_MSB,
+		 sparx5, ANA_L3_ARP_CFG_0(offset));
+
+	spx5_wr(mac_lsb, sparx5, ANA_L3_ARP_CFG_1(offset));
+}
