 static int
 sparx5_rr_lpm_arp_entry_create(struct sparx5 *sparx5,
 			       struct sparx5_iaddr *addr,
@@ -462,6 +1312,447 @@ sparx5_rr_lpm_arp_entry_create(struct sparx5 *sparx5,
